contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint dummy) public payable {
        require(dummy == 0);
        require(address(c).balance == 0);
        require(c.balances(address(this)) == 0);
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && c.balances(address(this)) == 0 && address(c).balance == 0);
    }
    receive() external payable {}
}

